<?php namespace SimpleCdn\lib; class Auth { protected static $loggedIn = false; public static function init(): void { if (session_status() === PHP_SESSION_NONE) { session_start(); } $config = self::loadConfig(); $password = $config['admin_password'] ?? ''; if (!empty($_SESSION['cdn_admin_logged_in'])) { self::$loggedIn = true; return; } if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['cdn_admin_action']) && $_POST['cdn_admin_action'] === 'login' ) { $input = $_POST['admin_password'] ?? ''; if ($password !== '' && $input === $password) { $_SESSION['cdn_admin_logged_in'] = true; self::$loggedIn = true; header('Location: ' . self::selfUrl()); exit; } else { $_SESSION['cdn_admin_error'] = '密码错误'; } } if (!$password) { self::$loggedIn = true; return; } if (!self::$loggedIn) { self::showLogin(); exit; } } public static function check(): void { if (session_status() === PHP_SESSION_NONE) { session_start(); } if (!empty($_SESSION['cdn_admin_logged_in'])) { self::$loggedIn = true; } } public static function isLoggedIn(): bool { return self::$loggedIn; } public static function logout(): void { session_start(); $_SESSION = []; if (isset($_COOKIE[session_name()])) { setcookie(session_name(), '', time() - 3600, '/'); } session_destroy(); header('Location: ' . self::selfUrl()); exit; } protected static function loadConfig(): array { $file = __DIR__ . '/../../config.php'; if (is_file($file)) { $cfg = include $file; if (is_array($cfg)) { return $cfg; } } $envPassword = getenv('SIMPLE_CDN_ADMIN_PASSWORD'); if ($envPassword !== false && $envPassword !== '') { return ['admin_password' => $envPassword]; } return []; } protected static function selfUrl(): string { $scheme = isset($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off' ? 'https' : 'http'; $host = $_SERVER['HTTP_HOST'] ?? 'localhost'; $script = $_SERVER['SCRIPT_NAME'] ?? '/admin/index.php'; if (basename($script) === 'router.php') { $script = $_SERVER['REQUEST_URI'] ?? '/admin/'; $script = strpos($script, '?') !== false ? substr($script, 0, strpos($script, '?')) : $script; if ($script === '' || $script === '/') { $script = '/admin/'; } } return $scheme . '://' . $host . $script; } protected static function showLogin(): void { $error = ''; if (!empty($_SESSION['cdn_admin_error'])) { $error = htmlspecialchars($_SESSION['cdn_admin_error']); unset($_SESSION['cdn_admin_error']); } ?> <!DOCTYPE html> <html lang="zh-CN"> <head> <meta charset="UTF-8"> <title>Simple CDN 后台登录</title> <style> body{font-family:system-ui,-apple-system,Segoe UI,Microsoft YaHei,sans-serif;background:#f5f7fa;color:#111;display:flex;align-items:center;justify-content:center;height:100vh;margin:0} .card{background:#fff;padding:32px;border-radius:12px;box-shadow:0 4px 24px rgba(0,0,0,.08);width:320px} h1{margin:0 0 16px;font-size:20px;color:#0f172a} label{display:block;margin-bottom:6px;font-size:13px;color:#475569} input[type=password]{width:100%;padding:10px;border:1px solid #e2e8f0;border-radius:6px;box-sizing:border-box;font-size:14px;margin-bottom:14px} button{width:100%;padding:10px;background:#2563eb;color:#fff;border:none;border-radius:6px;font-size:14px;cursor:pointer} button:hover{background:#1d4ed8} .msg{color:#dc2626;font-size:13px;margin-bottom:12px} .hint{font-size:12px;color:#64748b;margin-top:12px} </style> </head> <body> <div class="card"> <h1>Simple CDN 后台</h1> <?php if ($error): ?> <div class="msg"><?php echo $error; ?></div> <?php endif; ?> <form method="POST" action=""> <input type="hidden" name="cdn_admin_action" value="login"> <label>后台密码</label> <input type="password" name="admin_password" placeholder="输入后台密码" autocomplete="current-password"> <button type="submit">登录</button> </form> <div class="hint">密码在 simple-cdn/config.php 的 admin_password 中设置</div> </div> </body> </html> <?php } }